import random

n = 25

def girth(edges, n):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    min_cycle = n + 1
    for s in range(n):
        dist = [-1] * n
        parent = [-1] * n
        dist[s] = 0
        queue = [s]
        for u in queue:
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif v != parent[u] and dist[u] + dist[v] + 1 < min_cycle:
                    min_cycle = dist[u] + dist[v] + 1
        if min_cycle <= 6:
            return min_cycle
    return min_cycle

def is_5_colorable(edges, n):
    """Check if graph is 5-colorable using greedy or backtracking."""
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # Try greedy coloring with different orderings
    vertices = list(range(n))
    for _ in range(100):
        random.shuffle(vertices)
        colors = [-1] * n
        ok = True
        for v in vertices:
            used = set()
            for u in adj[v]:
                if colors[u] != -1:
                    used.add(colors[u])
            for c in range(5):
                if c not in used:
                    colors[v] = c
                    break
            if colors[v] == -1:
                ok = False
                break
        if ok:
            return True, colors
    return False, None

